package com.onlinelearning.controller;
import com.onlinelearning.model.*; import com.onlinelearning.repository.*; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.List;
@RestController @RequestMapping("/api/courses") public class CourseController {private final CourseRepository courses;private final UserRepository users;public CourseController(CourseRepository c,UserRepository u){courses=c;users=u;} public record Request(String title,String description,String category,Long instructorId){} @GetMapping public List<Course> all(@RequestParam(required=false)String search){return search==null||search.isBlank()?courses.findAll():courses.findByTitleContainingIgnoreCase(search);} @GetMapping("/{id}") public Course get(@PathVariable Long id){return courses.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Course not found"));} @PostMapping @PreAuthorize("hasAnyRole('INSTRUCTOR','ADMIN')") public Course create(@RequestBody Request r){User i=users.findById(r.instructorId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Instructor not found"));return courses.save(new Course(r.title(),r.description(),r.category(),i));} @PutMapping("/{id}") @PreAuthorize("hasAnyRole('INSTRUCTOR','ADMIN')") public Course update(@PathVariable Long id,@RequestBody Request r){Course c=get(id);c.setTitle(r.title());c.setDescription(r.description());c.setCategory(r.category());return courses.save(c);} @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public void delete(@PathVariable Long id){courses.deleteById(id);}}